      "reason": "Neither the definition nor the quoted contract establishes which tour buses or limousines have the required permission or that every permitted member carries ru.emergency_vehicle."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "underdetermined",
      "reason": "Neither the definition nor the quoted contract establishes which trailers or combinations have the required permission or that every permitted member carries ru.emergency_vehicle."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "underdetermined",
      "reason": "Neither the definition nor the quoted contract establishes which transit buses have the required permission or that every permitted transit bus carries ru.emergency_vehicle."
    },
    {
      "class": "ru.truck",
      "verdict": "underdetermined",
      "reason": "Neither the definition nor the quoted contract establishes which trucks have the required permission or that every permitted truck carries ru.emergency_vehicle."
    },
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The required vehicle category expressly excludes devices moved by human power, matching this class's human-powered contract."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "The required vehicle category expressly excludes electric bicycles, matching the class identified through the jurisdiction's electric-bicycle taxonomy."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "The required vehicle category expressly names electric scooters as an exception."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "The exception for devices used exclusively upon stationary rails describes the class's trains, trams, streetcars and other on-track equipment."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The admitting words require a transport device, whereas this class describes a person rather than the device the person may use."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The admitting words require a transport device, whereas this class describes a pedestrian who is a child."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The admitting words require a transport device, whereas this class describes a pedestrian with specified assistance."
    }
  ]
}

